<?php
$crmTitle = 'Kelola Jadwal Grup';
$status = (string)($_GET['status'] ?? 'aktif');
if (!in_array($status, ['aktif','terkirim','gagal','semua'], true)) $status = 'aktif';
$where = match ($status) { 'aktif' => "WHERE j.status='pending'", 'terkirim' => "WHERE j.status='terkirim'", 'gagal' => "WHERE j.status='gagal'", default => '' };
$rows = [];
$sql = "SELECT j.id,j.id_grup,j.pesan,j.tipe_jadwal,j.jadwal_kirim,j.jam_harian,j.hari_rutin,j.status,j.terakhir_dikirim,COALESCE(w.nama_grup,j.id_grup) nama_grup FROM jadwal_pesan_grup j LEFT JOIN wa_grup w ON w.id_grup=j.id_grup $where ORDER BY j.id DESC LIMIT 300";
$res = $conn->query($sql); if ($res) $rows = $res->fetch_all(MYSQLI_ASSOC);
$counts = ['aktif'=>crmCount($conn,"SELECT COUNT(*) total FROM jadwal_pesan_grup WHERE status='pending'"),'terkirim'=>crmCount($conn,"SELECT COUNT(*) total FROM jadwal_pesan_grup WHERE status='terkirim'"),'gagal'=>crmCount($conn,"SELECT COUNT(*) total FROM jadwal_pesan_grup WHERE status='gagal'")];
$dayMap=[1=>'Sen',2=>'Sel',3=>'Rab',4=>'Kam',5=>'Jum',6=>'Sab',7=>'Min'];
?>
<section class="page-head"><div><span class="eyebrow">Broadcast · Pengelolaan</span><h1>Kelola Jadwal Grup</h1><p>Pantau jadwal sekali dan rutin langsung dari CRM.</p></div><a class="group-manage-link" href="?page=group"><i class="fa-solid fa-arrow-left"></i> Kembali ke Broadcast</a></section>
<section class="group-schedule-stats">
<a class="group-schedule-stat <?= $status==='aktif'?'active':'' ?>" href="?page=group-schedules&status=aktif"><span>Aktif / menunggu</span><strong><?= $counts['aktif'] ?></strong></a>
<a class="group-schedule-stat <?= $status==='terkirim'?'active':'' ?>" href="?page=group-schedules&status=terkirim"><span>Terkirim</span><strong><?= $counts['terkirim'] ?></strong></a>
<a class="group-schedule-stat <?= $status==='gagal'?'active':'' ?>" href="?page=group-schedules&status=gagal"><span>Gagal</span><strong><?= $counts['gagal'] ?></strong></a></section>
<section class="group-card group-schedule-management"><div class="group-card-head"><div><span class="group-kicker">Daftar jadwal</span><h2>Jadwal <?= htmlspecialchars($status) ?></h2><p class="group-schedule-caption">Maksimal 300 jadwal terbaru. Jadwal rutin tetap aktif setelah dikirim.</p></div><form method="get" class="group-schedule-filter"><input type="hidden" name="page" value="group-schedules"><label for="groupScheduleStatus">Status</label><select id="groupScheduleStatus" name="status" onchange="this.form.submit()"><?php foreach(['aktif'=>'Aktif / menunggu','terkirim'=>'Terkirim','gagal'=>'Gagal','semua'=>'Semua'] as $v=>$label): ?><option value="<?= $v ?>" <?= $status===$v?'selected':'' ?>><?= htmlspecialchars($label) ?></option><?php endforeach; ?></select></form></div>
<?php if (!$rows): ?><div class="group-empty"><i class="fa-regular fa-calendar-xmark"></i><strong>Tidak ada jadwal</strong><span>Tidak ada data pada filter ini.</span></div><?php else: ?><div class="group-schedule-table-wrap"><table class="group-schedule-table"><thead><tr><th>Grup</th><th>Pesan</th><th>Jadwal</th><th>Status</th><th>Terakhir dikirim</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><strong><?= htmlspecialchars($r['nama_grup']) ?></strong><small>ID #<?= (int)$r['id'] ?></small></td><td class="group-schedule-message"><?= htmlspecialchars(mb_strimwidth((string)$r['pesan'],0,100,'…')) ?></td><td><span class="group-schedule-type"><?= htmlspecialchars(ucfirst((string)$r['tipe_jadwal'])) ?></span><?php if($r['tipe_jadwal']==='sekali'): ?><small><?= htmlspecialchars(date('d M Y · H:i',strtotime((string)$r['jadwal_kirim']))) ?></small><?php elseif($r['tipe_jadwal']==='harian'): ?><small><?= htmlspecialchars(substr((string)$r['jam_harian'],0,5)) ?> · <?= htmlspecialchars(implode(', ', array_map(fn($d) => $dayMap[(int)trim($d)] ?? trim($d), explode(',', (string)$r['hari_rutin']))) ) ?></small><?php endif; ?></td><td><span class="group-schedule-status status-<?= htmlspecialchars((string)$r['status']) ?>"><?= htmlspecialchars(ucfirst((string)$r['status'])) ?></span></td><td><?= !empty($r['terakhir_dikirim'])?htmlspecialchars(date('d M Y',strtotime((string)$r['terakhir_dikirim']))):'—' ?></td><td><?php if($r['status']==='pending'): ?><form method="post" action="actions/group-schedules.php" onsubmit="return confirm('Batalkan jadwal untuk grup ini?');"><input type="hidden" name="csrf" value="<?= htmlspecialchars(crmCsrfToken()) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="group-schedule-cancel" type="submit">Batalkan</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
